import requests
from pathlib import Path
import zipfile
DOWNLOAD_DIR = Path("downloads")
ZIP_DIR = Path("unzipped_files")
def task_func(url, filename):
    DOWNLOAD_DIR.mkdir(parents=True, exist_ok=True)
    ZIP_DIR.mkdir(parents=True, exist_ok=True)
    zip_path = DOWNLOAD_DIR / filename
    try:
        response = requests.get(url, stream=True, timeout=10)
        response.raise_for_status()
        with open(zip_path, "wb") as f:
            for chunk in response.iter_content(chunk_size=8192):
                if chunk:
                    f.write(chunk)
    except requests.RequestException as e:
        return (f"Error downloading file: {e}", [])
    try:
        with zipfile.ZipFile(zip_path, "r") as zf:
            zf.extractall(ZIP_DIR)
    except (FileNotFoundError, zipfile.BadZipFile, OSError) as e:
        return (f"Error extracting file: {e}", [])
    filenames = []
    for p in ZIP_DIR.rglob("*"):
        if p.is_file():
            filenames.append(str(p))
    return ("Download and extraction successful", filenames)

