import requests
from lxml import html
import pandas as pd
import sqlite3
def task_func(webpage_url: str, database_name: str = "my_database.db") -> int:
    content = None
    is_url = webpage_url.startswith("http://") or webpage_url.startswith("https://")
    if is_url:
        try:
            response = requests.get(webpage_url)
            response.raise_for_status()
            content = response.text
        except requests.RequestException as e:
            raise requests.RequestException(f"Error fetching URL: {e}")
    else:
        with open(webpage_url, "r", encoding="utf-8") as f:
            content = f.read()
    if not content:
        return 0
    tree = html.fromstring(content)
    tables = tree.xpath("//table")
    if not tables:
        return 0
    table = tables[0]
    rows = table.xpath(".//tr")
    if not rows:
        return 0
    header_cells = rows[0].xpath(".//th")
    headers = [h.text_content().strip() for h in header_cells] if header_cells else None
    data_rows = []
    start_index = 1 if header_cells else 0
    for row in rows[start_index:]:
        cols = row.xpath(".//td")
        if not cols:
            continue
        data_rows.append([c.text_content().strip() for c in cols])
    if not data_rows:
        return 0
    if headers and len(headers) != len(data_rows[0]):
        headers = None
    df = pd.DataFrame(data_rows, columns=headers if headers else None)
    try:
        conn = sqlite3.connect(database_name)
        df.to_sql("my_table", conn, if_exists="replace", index=False)
        conn.close()
    except sqlite3.DatabaseError as e:
        raise sqlite3.DatabaseError(f"Database error: {e}")
    return len(df)

import requests
from lxml import html
import pandas as pd
import sqlite3
def task_func(webpage_url: str, database_name: str = "my_database.db") -> int:
    if not isinstance(webpage_url, str) or not webpage_url:
        return 0
    if webpage_url.startswith("http://") or webpage_url.startswith("https://"):
        try:
            response = requests.get(webpage_url)
            response.raise_for_status()
            content = response.text
        except requests.RequestException as e:
            raise requests.RequestException(str(e))
    else:
        try:
            with open(webpage_url, "r", encoding="utf-8") as f:
                content = f.read()
        except OSError:
            return 0
    try:
        tree = html.fromstring(content)
        table_elements = tree.xpath("//table")
        if not table_elements:
            return 0
        table_html = html.tostring(table_elements[0], encoding="unicode")
        dfs = pd.read_html(table_html)
        if not dfs:
            return 0
        df = dfs[0]
        if df.empty:
            return 0
    except Exception:
        return 0
    try:
        conn = sqlite3.connect(database_name)
        try:
            df.to_sql("my_table", conn, if_exists="replace", index=False)
        except sqlite3.DatabaseError as e:
            raise sqlite3.DatabaseError(str(e))
        finally:
            conn.close()
    except sqlite3.DatabaseError as e:
        raise sqlite3.DatabaseError(str(e))
    return len(df)

