import json
import requests
import os
from datetime import datetime
def task_func(json_data, unknown_key, save_dir=None):
    if not isinstance(json_data, str) or not json_data:
        raise ValueError("json_data must be a non-empty JSON string")
    if not isinstance(unknown_key, str) or not unknown_key:
        raise ValueError("unknown_key must be a non-empty string")
    try:
        data = json.loads(json_data)
    except json.JSONDecodeError as e:
        raise ValueError(f"Invalid JSON data: {e}")
    if unknown_key not in data:
        raise KeyError(f"Key '{unknown_key}' not found in JSON data")
    url = data[unknown_key]
    if not isinstance(url, str) or not url:
        raise ValueError(f"Value for key '{unknown_key}' must be a non-empty URL string")
    if save_dir is None:
        save_dir = os.getcwd()
    else:
        if not isinstance(save_dir, str) or not save_dir:
            raise ValueError("save_dir must be a non-empty string when provided")
    os.makedirs(save_dir, exist_ok=True)
    timestamp = datetime.now().strftime("%Y%m%d%H%M%S%f")
    filename = f"{unknown_key}_{timestamp}.txt"
    abs_path = os.path.abspath(os.path.join(save_dir, filename))
    try:
        response = requests.get(url, stream=True)
        response.raise_for_status()
    except requests.RequestException as e:
        raise ConnectionError(f"Failed to download file from URL '{url}': {e}")
    with open(abs_path, "wb") as f:
        for chunk in response.iter_content(chunk_size=8192):
            if chunk:
                f.write(chunk)
    return abs_path

