    except Exception:
        return ["Invalid url input"]
    if not isinstance(data, str):
        data_str = json.dumps(data)
    else:
        data_str = data
    bracket_ranges = []
    stack = []
    for i, ch in enumerate(data_str):
        if ch == '[':
            stack.append(i)
        elif ch == ']' and stack:
            start = stack.pop()
            bracket_ranges.append((start, i))
    def in_brackets(start, end):
        for b_start, b_end in bracket_ranges:
            if start >= b_start and end <= b_end:
                return True
        return False
    pattern = re.compile(r'\b[A-Z][a-zA-Z]+\b')
    names = []
    for m in pattern.finditer(data_str):
        if not in_brackets(m.start(), m.end()):
            names.append(m.group(0))
    return names

